import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.CWgsre3x.js";const f=JSON.parse('{"title":"Staff accounts and administration","description":"","frontmatter":{},"headers":[],"relativePath":"plus/staff-administration.md","filePath":"plus/staff-administration.md"}'),n={name:"plus/staff-administration.md"};function o(s,e,d,c,l,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="staff-accounts-and-administration" tabindex="-1">Staff accounts and administration <a class="header-anchor" href="#staff-accounts-and-administration" aria-label="Permalink to &quot;Staff accounts and administration&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed against TransferBook+ v0.7.26. Verify the installed release, company, permissions and configuration. Use authorized synthetic data for training. Commercial activation is not asserted.</p></div><h2 id="before-creating-a-login" tabindex="-1">Before creating a login <a class="header-anchor" href="#before-creating-a-login" aria-label="Permalink to &quot;Before creating a login&quot;">​</a></h2><p>A driver roster record and an authenticated staff account are different things. Do not assume that creating a driver in the fleet directory creates credentials. Staff provisioning is a privileged backend operation, not a public registration process.</p><h2 id="authorized-onboarding" tabindex="-1">Authorized onboarding <a class="header-anchor" href="#authorized-onboarding" aria-label="Permalink to &quot;Authorized onboarding&quot;">​</a></h2><ol><li>Confirm the person&#39;s identity, employment or contractual relationship, company and required duties. Record approval by the responsible administrator.</li><li>Ask the platform administrator to create the account and active company membership with the minimum required role. The inspected backend includes <code>scripts/provision-operator-user.mjs</code>, which accepts email, full name, company UUID and role, obtains an initial password from the protected process environment and stores a scrypt hash. This is a technical administrator tool, not an operator screen.</li><li>Supported roles in that provisioning tool are company_admin, dispatcher, driver and viewer. Do not grant platform administration through this tool. Verify any driver-to-account association separately; provisioning membership alone does not establish that association.</li><li>Deliver unique credentials securely. Use a strong password; never publish credentials, share accounts or reuse test passwords. Passenger email is optional, but the inspected staff login uses email and password.</li><li>Confirm sign-in, correct company, permitted screens and denied actions using the new user&#39;s actual role. For a chauffeur, verify access only to authorized assignments. Do not use administrator simulation as evidence of driver permissions.</li></ol><h2 id="changes-and-offboarding" tabindex="-1">Changes and offboarding <a class="header-anchor" href="#changes-and-offboarding" aria-label="Permalink to &quot;Changes and offboarding&quot;">​</a></h2><p>The provisioning script updates credentials and reactivates existing accounts/memberships when the normalized email already exists. Treat rerunning it as a sensitive account change, not harmless duplication. Require authorization and verify existing memberships before a reset. For departures, have the authorized backend administrator revoke membership, sessions and any sharing authorization; verify subsequent access is denied. Do not delete operational history to remove access.</p><p>Public driver/staff/partner applications, if introduced, must be reviewed before backend provisioning. No automatic account activation or general self-service staff administration interface is asserted for this release.</p><p>See <a href="/developers/authentication.html">Authentication</a>, <a href="/developers/permissions.html">Roles and permissions</a> and <a href="/plus/drivers-and-rosters.html">Drivers and rosters</a>.</p>',10)])])}const m=a(n,[["render",o]]);export{f as __pageData,m as default};
